SELECT `t1`.`id` AS `id`, `t1`.`board_id` AS `boardId`, `t1`.`user_id` AS `userId`, `t1`.`participants_id` AS `participantsId`, `t1`.`wallet_id` AS `walletId`, `t1`.`title` AS `title`, `t1`.`menu` AS `menu`, `t1`.`menu_name` AS `menuName`, `t1`.`min_order_price` AS `minOrderPrice`, `t1`.`order_price` AS `orderPrice`, `t1`.`delivery_price` AS `deliveryPrice`, `t1`.`order_time` AS `orderTime`, `t1`.`pickup_time` AS `pickupTime`, `t1`.`restaurant` AS `restaurant`, `t1`.`restaurant_lat` AS `restaurantLat`, `t1`.`restaurant_lng` AS `restaurantLng`, `t1`.`address_primary` AS `addressPrimary`, `t1`.`address_secondary` AS `addressSecondary`, `t1`.`content` AS `content`, `t1`.`isShareChecked` AS `IsShareChecked`, `t1`.`isEntryChecked` AS `IsEntryChecked`, `t1`.`created_at` AS `createdAt`, `t1`.`updated_at` AS `updatedAt`, `t1`.`view` AS `view` FROM `kkirikkiri`.`articles` AS `t1` WHERE `t1`.`board_id` = #{boardSearch.id}
AND (`t1`.`title` LIKE CONCAT('%', #{boardSearch.keyword}, '%') OR `t1`.`content` LIKE CONCAT('%', #{boardSearch.keyword}, '%') OR `t1`.`user_id` LIKE CONCAT('%', #{boardSearch.keyword}, '%'))
AND `t1`.`title` LIKE CONCAT('%', #{boardSearch.keyword}, '%')
AND `t1`.`user_id` = #{boardSearch.keyword}
ORDER BY `t1`.`id` DESC LIMIT #{boardPage.rowCount} OFFSET #{boardPage.dbOffset}

SELECT COUNT(0)
FROM `kkirikkiri`.`articles` AS `t1`
WHERE `t1`.`board_id` = #{boardSearch.id}

    AND (
    `t1`.`title` LIKE CONCAT('%', #{boardSearch.keyword}, '%')
    OR `t1`.`content` LIKE CONCAT('%', #{boardSearch.keyword}, '%')
    OR `t1`.`user_id` LIKE CONCAT('%', #{boardSearch.keyword}, '%')
    )



    AND `t1`.`title` LIKE CONCAT('%', #{boardSearch.keyword}, '%')



    AND `t1`.`user_id` = #{boardSearch.keyword}

SELECT `t1`.`id` AS `id`, `t1`.`board_id` AS `boardId`, `t1`.`user_id` AS `userId`, `t1`.`participants_id` AS `participantsId`, `t1`.`wallet_id` AS `walletId`, `t1`.`title` AS `title`, `t1`.`menu` AS `menu`, `t1`.`menu_name` AS `menuName`, `t1`.`min_order_price` AS `minOrderPrice`, `t1`.`order_price` AS `orderPrice`, `t1`.`delivery_price` AS `deliveryPrice`, `t1`.`order_time` AS `orderTime`, `t1`.`pickup_time` AS `pickupTime`, `t1`.`restaurant` AS `restaurant`, `t1`.`restaurant_lat` AS `restaurantLat`, `t1`.`restaurant_lng` AS `restaurantLng`, `t1`.`address_primary` AS `addressPrimary`, `t1`.`address_secondary` AS `addressSecondary`, `t1`.`content` AS `content`, `t1`.`isShareChecked` AS `IsShareChecked`, `t1`.`isEntryChecked` AS `IsEntryChecked`, `t1`.`created_at` AS `createdAt`, `t1`.`updated_at` AS `updatedAt`, `t1`.`view` AS `view` FROM `kkirikkiri`.`articles`AS `t1` WHERE `board_id` = #{boardId} AND AND `order_time` IS NOT NULL AND `order_time` BETWEEN NOW() AND DATE_ADD(NOW(), INTERVAL 30 MINUTE)
AND `menu` = #{menu}
ORDER BY `orderTime` ASC LIMIT 10
